-- Applied as kus_music_cross_provider_playlist_entry_policy_fix on 2026-11-13.
drop policy if exists "Owners and editors manage catalogue playlist entries" on public.music_playlist_catalog_entries;
drop policy if exists "Owners and editors add catalogue playlist entries" on public.music_playlist_catalog_entries;
create policy "Owners and editors add catalogue playlist entries" on public.music_playlist_catalog_entries for insert to authenticated with check(added_by=(select auth.uid()) and exists(select 1 from public.music_playlists p where p.id=playlist_id and (p.user_id=(select auth.uid()) or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=p.id and c.user_id=(select auth.uid()) and c.status='accepted' and c.role='editor'))));
drop policy if exists "Owners and editors update catalogue playlist entries" on public.music_playlist_catalog_entries;
create policy "Owners and editors update catalogue playlist entries" on public.music_playlist_catalog_entries for update to authenticated using(exists(select 1 from public.music_playlists p where p.id=playlist_id and (p.user_id=(select auth.uid()) or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=p.id and c.user_id=(select auth.uid()) and c.status='accepted' and c.role='editor')))) with check(exists(select 1 from public.music_playlists p where p.id=playlist_id and (p.user_id=(select auth.uid()) or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=p.id and c.user_id=(select auth.uid()) and c.status='accepted' and c.role='editor'))));
drop policy if exists "Owners and editors delete catalogue playlist entries" on public.music_playlist_catalog_entries;
create policy "Owners and editors delete catalogue playlist entries" on public.music_playlist_catalog_entries for delete to authenticated using(exists(select 1 from public.music_playlists p where p.id=playlist_id and (p.user_id=(select auth.uid()) or exists(select 1 from public.music_playlist_collaborators c where c.playlist_id=p.id and c.user_id=(select auth.uid()) and c.status='accepted' and c.role='editor'))));
